for n in ['Tripura iron city','Tripura gold city','Tripura silver city']:rel('Tripura','receives_city',n,e)
e,v=ev(39,'1–9','After Vyāsa’s question, Tripura installs a Gaṇeśa image of Kashmir stone with mantra-skilled Brahmins, builds a gold jewelled temple at Gaṇeśapura, offers sixteen services, praise/bows, asks leave and gives donations. Gaṇeśapura is situated in Bengal and promises success. He rules human world, recruits the fourfold army from all directions, receives compliant kings’ service and kills opposing rulers.',[('Vyāsa',S),('Brahmā',D),('Tripura',A),('Gaṇeśa',D),('Tripura Gaṇeśapura',L),('Bengal',L),('Kashmir stone',C),('Tripura army','ARMY'),('Mantra-skilled image-installing Brahmins','FAMILY'),('Subjugated human kings','FAMILY')],story='gup2-story-tripura',cause='City boon leads to worship/installation before conquest.',outcome='Temple established; human sovereignty gained.')
rel('Tripura','installs','Gaṇeśa',e);rel('Tripura','rules','Tripura Gaṇeśapura',e);rel('Tripura Gaṇeśapura','located_in','Bengal',e)
e,v=ev(39,'10–20','Tripura moves on Amarāvatī; armed Indra emerges on Airāvata. Tripura divides his fourfold army into thirds, appoints Bhīmakāya lord of human world and addresses Kālakūṭa/Vajradaṃṣṭra to lead a third to Rasātala and subdue Śeṣa’s Nāgas, taking a third himself against Indra. Bhīmakāya/Vajradaṃṣṭra depart as ordered. Troops break Nandana trees despite resistance. Messengers demand Indra attend Tripura or leave for mortal world where he will be protected; surrender Amarāvatī peacefully or fight.',[('Tripura',A),('Indra',D),('Airāvata',F),('Amarāvatī',L),('Nandana',L),('Bhīmakāya',A),('Kālakūṭa',A),('Vajradaṃṣṭra',A),('Śeṣa',D),('Nāgas',C),('Rasātala',L),('Tripura messengers','FAMILY'),('Tripura army','ARMY')],story='gup2-story-tripura',cause='Conquest expands from human realm to gods and underworld.',outcome='Threefold campaign and surrender ultimatum delivered.')
rel('Bhīmakāya','commander_under','Tripura',e);rel('Vajradaṃṣṭra','commander_under','Tripura',e);rel('Kālakūṭa','addressed_in_underworld_order_by','Tripura',e)
e,v=ev(39,'21–35','Indra trembles, ponders then rages and orders messengers to summon battle, roaring from Airāvata. Gods equip swords, bhiṇḍipāla, śakti/ṛṣṭi, clubs, bows/arrows, maces/shields and staffs; Brahmins perform auspicious rites. Tripura emerges mounted on horse with vast army. His huṃkāra sends troops into chaotic mutual slaughter; many on both sides die or lose limbs and vehicle troops fall. Daityas initially flee.',[('Indra',D),('Tripura',A),('Airāvata',F),('God army','ARMY'),('Tripura army','ARMY'),('Tripura horse','VAHANA'),('Swords',W),('Bhiṇḍipāla',W),('Śakti spears',W),('Ṛṣṭi spears',W),('Clubs',W),('Bows',W),('Arrows',W),('Maces',W),('Shields',W),('Staffs',W)],story='gup2-story-tripura',cause='Indra rejects surrender and both armies deploy.',outcome='Mass battle first breaks daitya ranks.')
rel('Indra','rides','Airāvata',e);rel('Tripura','rides','Tripura horse',e)
e,v=ev(39,'36–40','Tripura checks fleeing troops and personally attacks Indra’s vajra-bearing hand with sword. Fallen vajra he seizes and uses against Airāvata, driving elephant away. Indra punches him down, but risen Tripura punches Indra onto earth.',[('Tripura',A),('Indra',D),('Airāvata',F),('Tripura sword',W),('Indra vajra',W)],story='gup2-story-tripura',cause='Initial army setback prompts personal counterattack.',outcome='Indra disarmed and mount routed; fist exchange begins.')
rel('Tripura','seizes_and_uses','Indra vajra',e)
e,v=ev(39,'41–50','Indra demands wrestling. Tripura asks why he risks dear life and offers mortal-world refuge; Indra stakes departure on inability to kill opponent and predicts Tripura’s fall. They strike chest/hands/knees/thighs/heads/elbows/backs/feet, compared with Kṛṣṇa/Cāṇūra. Tripura grabs Indra’s feet, whirls and throws him far out of sight, then mounts four-tusked Airāvata.',[('Tripura',A),('Indra',D),('Airāvata',F),('Kṛṣṇa',D),('Cāṇūra',A)],story='gup2-story-tripura',cause='Indra rejects opponent’s refuge offer.',outcome='Wrestling ends in Indra’s expulsion; Tripura captures mount.')
rel('Tripura','rides','Airāvata',e)
e,v=ev(39,'51–57','Gods seek Indra in Himalayan caves and find him arriving downcast, embracing/worshipping/fanning/massaging him. They remain secretly there. Tripura enters Amarāvatī on Airāvata, occupies Indra’s throne and assigns divine offices individually to daityas; he enjoys music and service of Gandharvas, Kinnaras and Apsarases.',[('Tripura',A),('Indra',D),('Airāvata',F),('Himalayan caves',L),('Amarāvatī',L),('Gods',C),('Gandharvas',C),('Kinnaras',C),('Apsarases',C),('Daitya officeholders','FAMILY')],story='gup2-story-tripura',cause='Indra’s defeat displaces divine rulers.',outcome='Daitya rule installed; gods hide and recover together.')
rel('Tripura','occupies','Amarāvatī',e)
e,v=ev(40,'1–9','Tripura goes to Brahmā’s abode; forewarned Brahmā withdraws to Viṣṇu’s navel-lotus and Viṣṇu to milk-ocean. Tripura installs mental sons Pracaṇḍa in Brahmaloka and Caṇḍa in Vaikuṇṭha. At Kailāsa his shaking frightens Girijā, who embraces Śiva. Pleased by daitya prowess Śiva offers a boon; Tripura requests Kailāsa and asks Śiva to move to Mandāra as long as his wish lasts. Śiva grants Kailāsa for a short time and departs with attendants.',[('Tripura',A),('Brahmā',D),('Viṣṇu',D),('Pracaṇḍa',A),('Caṇḍa',A),('Brahmaloka',L),('Vaikuṇṭha',L),('Milk-ocean',L),('Viṣṇu navel-lotus',C),('Kailāsa',L),('Girijā',D),('Śiva',D),('Mandāra',L),('Śiva attendants','ARMY')],story='gup2-story-tripura',cause='Success over Indra extends to higher abodes.',outcome='Sons occupy two divine realms; brief Kailāsa grant moves Śiva to Mandāra.')
for n in ['Pracaṇḍa','Caṇḍa']:rel(n,'child_of','Tripura',e,'MANASA_SON')
rel('Pracaṇḍa','rules','Brahmaloka',e);rel('Caṇḍa','rules','Vaikuṇṭha',e)
power('Tripura',e,v,typ='BOON',grant='Śiva',motive='Śiva is pleased by daitya’s prowess.',requested='Give Kailāsa and move to Mandāra for duration of Tripura’s wish.',granted='Kailāsa temporarily.',duration='Short time (svalpakālina), not an exact numerical term.')
e,v=ev(40,'10–17','Bhīmakāya subdues kings, imprisons sages, destroys sacrificial fire-pits, āśramas and tīrthas, terrorizes ascetics and opposes svāhā/svadhā/vaṣaṭ, Vedic study and good conduct. Vajradaṃṣṭra subdues seven lower worlds including Śeṣa, Vāsuki, Takṣaka and poisonous/nonpoisonous serpents; he enjoys gems/Nāga women, brings treasure and report to Tripura, and receives honour, rich clothes, villages and slaves.',[('Bhīmakāya',A),('Vajradaṃṣṭra',A),('Tripura',A),('Śeṣa',D),('Vāsuki',D),('Takṣaka',F),('Nāgas',C),('Nāga women','FAMILY'),('Captive sages','FAMILY'),('Seven lower worlds',L)],story='gup2-story-tripura',cause='Regional commands extend the conquest.',outcome='Ritual support suppressed; underworld treasure and allegiance reported.')
e,v=ev(40,'18–33','Hidden gods wonder when/by whom Tripura dies and who gave boon. Nārada arrives, receives welcome, hears plea for refuge/remedy and explains a Gaṇeśa boon secured by intense1,000-divine-year austerity as his report here: no fear from gods/sages/ancestors/beings/Yakṣas/Rākṣasas/Piśācas/Nāgas except Śaṅkara. He urges Gaṇeśa worship; asked method, he initiates all in one-syllable mantra and instructs steadfast practice until deity personally gives killing strategy, then departs singing vīṇā.',[('Gods',C),('Nārada',S),('Tripura',A),('Gaṇeśa',D),('Śiva',D),('Single-syllable Gaṇeśa mantra',T),('Ancestors',C),('Yakṣas',C),('Rākṣasas',C),('Piśācas',C),('Nāgas',C)],story='gup2-story-tripura',cause='Displaced gods seek explanation and remedy.',outcome='Nārada supplies initiation and divine-refuge strategy; duration differs from38 direct scene.')
rel('Nārada','initiates','Gods',e);rel('Nārada','teaches_mantra','Single-syllable Gaṇeśa mantra',e)
variant('tripura-duration','Tripura direct practice38.21 says15,000years; Nārada’s40.25 retrospective says1,000divine years. Both witness statements retained as source-local discrepancy, not harmonized.',e)
d['variants_and_conflicts'][-1]['evidence_ids'].append(e_aust)
e,v=ev(40,'34–41','Gods fast and restrain breath, adopting one-foot, lotus or warrior postures, closed eyes and Gaṇeśa meditation/mantra. After long unspecified time he appears crowned and jeweled, bearing noose, goad, axe and lotus, scented/red/moon-adorned and immensely radiant. Some fear, bow, worship or praise for distress removal.',[('Gods',C),('Gaṇeśa',D),('Gaṇeśa noose',W),('Gaṇeśa goad',W),('Gaṇeśa axe',W),('Gaṇeśa lotus',C),('Single-syllable Gaṇeśa mantra',T)],story='gup2-story-tripura',cause='Nārada’s instructions are followed.',outcome='Divine appearance enables collective boon request.')
